from h34 import *
M=mcq;F=tf;S=short;N=num
chapter(3,'evs','celebrating-festivals','Celebrating Festivals',
 ('Rishi visits the mountains in spring','Rishi from Jammu travels by bus with his parents to meet his Mama, Mami and cousins Chiya and Nonikaa in a village near the mountains. It is spring, and the garden is full of flowers. Over lunch the children talk about the festivals they celebrate in spring and the special food that goes with each festival.'),
 [('The journey and road safety',['Rishi\'s bus climbs roads with hairpin turns, and the hills are covered with colourful flowers and tall trees.','When we travel we should sit properly, keep our hands and heads inside and listen to elders. When we ride a bicycle or walk, we should follow the road rules.','Road signboards help us stay safe. No Parking tells us not to park a vehicle there, No Horn Please asks us not to blow the horn, Speed Breaker warns of a bump, No U-Turn tells us not to turn back, Men at Work tells us that work is going on and School Ahead tells us to slow down.']),
  ('Spring and festivals of flowers',['In the village garden Rishi sees roses, marigolds and hibiscus and also tulips. A tulip is a flower that grows in the mountains in spring.','Spring is a celebration of nature. After the cold winter the sun shines brightly, flowers bloom, grass grows and trees get new leaves.','In Kashmir people celebrate a tulip festival in spring. In Rishi\'s place they put mustard and buransh flowers, red flowers called rhododendron, at the doorstep of each home, and the elders bless the children and give them sweets.','In Kerala people celebrate Vishu at this time. They arrange yellow amaltas flowers, fruits and vegetables in Vishu Kani, an auspicious sight at sunrise on the first day of the Malayali new year.']),
  ('Food and clothes for festivals',['Each festival has special food. Thekua is made for Chhath Puja, pitha for Bihu, plum cake for Christmas, gujiya for Holi, sadya for Onam, holige for Ugadi and seviyan for Eid-ul-Fitr.','Rishi\'s mami serves a Kashmiri dish called haakh, a leafy vegetable, with hot rice.','People wear special dresses during festivals, and the dress, food and customs are different in different places.','Not everyone celebrates festivals in the same way. Some people have few things but they can still celebrate with joy.']),
  ('Why we celebrate together',['Festivals bring family, friends and neighbours together. We share food, sing songs and bless each other.','We celebrate festivals of every season: spring, summer, the monsoon and winter. We can ask our elders to tell us the festivals of our locality.','Being in nature, among flowers, mountains, rivers and streams, makes us feel happy.'])],
 [('Match the food with the festival: gujiya, sadya and seviyan.',[('Gujiya is made for Holi.','A sweet filled pastry for the festival of colours.'),('Sadya is a feast served on Onam.','A meal served on a banana leaf in Kerala.'),('Seviyan is prepared for Eid-ul-Fitr.','A sweet dish of fine noodles.')]),
  ('Why do people celebrate a spring festival?',[('After the harsh winter, spring brings sunshine and flowers.','The weather becomes pleasant.'),('Nature is renewed: new leaves, new grass and blossoms.','People feel happy.'),('So spring festivals thank nature and bring people together.','They celebrate with flowers, food and songs.')])],
 ('Tell about a festival you celebrate. Say the season, the food and what you do.',['Name the festival','The season or time','Special food and clothes','Who you celebrate with'],['Everyone celebrates the same festivals','Festivals need expensive things']),
 ['Festivals are celebrated in different seasons with special food, clothes and customs.','Spring is a celebration of nature with flowers and new leaves.','Road signs help us stay safe on a journey.','Festivals bring families and neighbours together.','Different places celebrate in different ways.'],
 [M('1',1,'Where does Rishi come from?','Jammu',[('Kerala','Kerala is Unni\'s home'),('Assam','The story says Jammu')],'Rishi is from Jammu.'),
  M('2',1,'Which flower did Nonikaa show Rishi?','Tulip',[('Rose','Rishi knew roses'),('Marigold','Rishi knew marigolds')],'Nonikaa pointed to a tulip.'),
  M('3',1,'Which food is made for Chhath Puja?','Thekua',[('Gujiya','Gujiya is made for Holi'),('Sadya','Sadya is for Onam')],'Thekua is a Chhath Puja sweet.'),
  M('4',1,'Which festival has Vishu Kani?','Vishu',[('Onam','Onam has sadya'),('Holi','Holi has colours')],'Vishu Kani is part of Vishu.'),
  M('5',2,'Which food goes with Eid-ul-Fitr?','Seviyan',[('Plum cake','That is for Christmas'),('Pitha','That is for Bihu')],'Seviyan is made for Eid-ul-Fitr.'),
  M('6',2,'What do signs like No Horn Please do?','Tell us the rules for safety',[('Show a festival','They are road signs'),('Sell something','They are not shops')],'Road signs keep us safe.'),
  S('7',2,'What are the red spring flowers of Rishi\'s place called?',['buransh','rhododendron','Buransh'],'Buransh, the rhododendron.'),
  F('8',2,'People in every place celebrate festivals in the same way.',False,'Food, clothes and customs differ.'),
  F('9',2,'Spring is the season after the harsh winter when flowers bloom.',True,'Spring brings sunshine and new leaves.'),
  M('10',2,'Which festival has gujiya?','Holi',[('Onam','Onam has sadya'),('Ugadi','Ugadi has holige')],'Gujiya is a Holi sweet.'),
  M('11',3,'What does a Speed Breaker sign warn us about?','A bump on the road',[('A school','That is School Ahead'),('A parking spot','That is No Parking')],'It tells us to slow down.'),
  M('12',3,'Why do festivals make us happy?','We share food and time with others',[('We stay alone','Festivals bring people together'),('We get no sweets','Sharing sweets is part of it')],'Festivals bring us together.')],
 keep=['festival','spring','tulip'])
